        return /\.(jpg|jpeg|png)$/.test(file.type);
      },
    }),
  ],
});
```

With this setup, users will be able to add URLs to the upload queue by clicking on the "Web URL" button in the Uppy interface. The plugin will automatically fetch the content of the URL and create an upload object for each valid URL found. Note that since the plugin doesn't authenticate the user, the URLs must be publicly accessible and contain only files that the user has permission

