```

Next, connect to your database and retrieve the chatroom ID:

```php
$roomId = getRoomId(); // assume this function returns the room ID from the database

// Create socket.io instance
$socket = new SocketIO();

// Connect to server
$socket->connect('http://localhost:3000');

// Join chatroom
$socket->emit('joinRoom', array('roomId' => $roomId));

// Listen for messages and broadcast them
$socket->on('message', function($data) use ($roomId) {
    // Save message to database
    saveMessageToDatabase($data['message'], $roomId, $data['sender']);

    // Broadcast message to all clients in the room
    $socket->broadcast->to($roomId)->emit('message', $data);
});

// Handle disconnection
$socket->on('disconnect', function() {
    // Remove user from chatroom
    removeUserFromChatroom($roomId, $socket->handshake->query['userId']);
});

// Start polling for updates
$socket->getNamespace('/')->adapter->poll();
```

