# Define function to check if an SID exists only in SIDHistory
function CheckSidInSidHistory($sid) {
    $domainController = "DC=your_domain,DC=com"
    $searchBase = "CN=System"
    $searchFilter = "(objectClass=Computer)"
    $searchResult = Get-ADObject -Filter $searchFilter -SearchBase $searchBase -Server $domainController -Properties * | Select-Object -ExpandProperty sidhistory

    foreach ($history in $searchResult) {
        if ([Security.Principal.NTAccount]$history.Value -match $sid) {
            return $true
        }
    }
    return $false
}

# Define function to get all folders and subfolders recursively
function GetFolders($path) {
    Get-ChildItem -Path $path -Recurse -ErrorAction SilentlyContinue | Where-Object {$_.PSIsContainer}
}

# Define function to retrieve ACL for folder
function GetACL($folder) {
    Get-Acl -Path $folder
}

# Define function to check if any SID in ACL refers to SIDHistory
function CheckForSidHistory($acl) {
    foreach ($access in $acl.Access) {
        $identityReference = $access.IdentityReference
        $sid = New-Object Security.Principal.SecurityIdentifier($identityReference)
        if (CheckSidInSidHistory($sid)) {
            Write-Host "$($access.IdentityReference) refers to SIDHistory."
            Return $true
        }
    }
    Return $false
}

# Define function to iterate through folders and check ACLs
function CheckFolderACL($folder) {
    $acl = GetACL($folder)
    $result = CheckForSidHistory($acl)
    if ($result) {
        Write-Host "Folder $folder has SIDHistory reference(s)."
    } else {
        Write-Host "Folder $folder does not have SIDHistory reference(s)."
    }
}

